const program16 = {
  id: 16,
  title: "Program 16 - String Reverse",
  lang: "c",
  code: `#include <stdio.h>
#include <string.h>

int main() {
    char s[200];
    fgets(s, sizeof s, stdin);
    int n = strlen(s);
    if (s[n-1]=='\\n') s[n-1]='\\0', n--;
    for (int i=n-1;i>=0;i--) putchar(s[i]);
    putchar('\\n');
    return 0;
}
`
};

export default program16;
